function walk(l){var a=[l];(l.layers||[]).forEach(k=>a=a.concat(walk(k)));return a;}['Light','Dark'].forEach(a=>{var p=H.page('Proto macOS '+a);p.layers.filter(s=>s.name.startsWith('Screen/')).forEach(s=>{var layers=walk(s);var issues=[];layers.filter(l=>l!==s&&l.parent&&l.parent.type!=='Page'&&l.type!=='HotSpot').forEach(l=>{var f=l.frame,p=l.parent.frame;if(f.x<-.6||f.y<-.6||f.x+f.width>p.width+.6||f.y+f.height>p.height+.6)issues.push({name:l.name,parent:l.parent.name,f:f,p:{w:p.width,h:p.height}});});var menu=layers.find(l=>l.name==='conversation-menu');var trigger=layers.find(l=>l.name==='header');var composer=layers.find(l=>l.name==='composer');H.out({name:s.name,id:s.id,x:s.frame.x,y:s.frame.y,w:s.frame.width,h:s.frame.height,links:layers.filter(l=>l.name.startsWith('link:')).map(l=>({name:l.name,id:l.id,type:l.type})),issues:issues,scrims:s.layers.filter(l=>l.type==='ShapePath'&&l.frame.width===1440).map(l=>({name:l.name,fill:l.style.fills.map(f=>f.color)})),menu:menu?menu.frame:null,composer:composer?composer.frame:null});});});